# Raspberry Pi GPIO output controller for a clean energy monitoring node
# Drives three digital outputs on BCM GPIO pins using gpiozero
from gpiozero import OutputDevice
import time
import logging

# Configure logging for the clean energy monitoring node
logging.basicConfig(level=logging.INFO)

# BCM pin assignments for the three energy monitoring outputs
OUTPUT_DEVICES = {
    "wind": OutputDevice(2),
    "solar": OutputDevice(3),
    "battery": OutputDevice(4),
}


def report_states():
    """Report the current state of each GPIO output."""
    # Iterate over the outputs and print their current state
    for output_device, state_name in OUTPUT_DEVICES.items():
        logging.info("%s state=%s", state_name, output_device.is_active)


def main():
    """Drive the energy monitoring outputs and report their state."""
    # Create the gpiozero outputs for the three monitoring pins
    outputs = {}
    for pin_number, output_device in OUTPUT_DEVICES.items():
        outputs[pin_number] = output_device
    try:
        # Drive each output to the active state for a short interval
        for pin_number, output_device in outputs.items():
            output_device.on()
            time.sleep(1)
            output_device.off()
        report_states()
    except RuntimeError as runtime_error:
        # Handle a missing GPIO device on the Raspberry Pi
        logging.error("GPIO device not found: %s", runtime_error)
    finally:
        # Release the GPIO outputs on exit
        for output_device in outputs.values():
            output_device.close()


if __name__ == "__main__":
    main()

from gpiozero import PWMOutputDevice
import time

# GPIO pins wired to the dynamo PWM channels
DYNAMO_CHANNELS = [PWMOutputDevice(4), PWMOutputDevice(17), PWMOutputDevice(22), PWMOutputDevice(27)]

def apply_dynamo_state(dynamo_devices, state_value):
    """Set all dynamo PWM devices to the requested state."""
    # Drive each channel to the requested on/off state
    for dynamo_device in dynamo_devices:
        dynamo_device.value = state_value
    return dynamo_devices

def is_dynamo_valid(dynamo_devices):
    """Return True when all dynamo channels report a valid state."""
    # A stopped dynamo reports zero duty cycle
    return all(channel.value == 1 for channel in dynamo_devices)

if __name__ == "__main__":
    dynamo_devices = []
    try:
        # Create a PWMOutputDevice per dynamo channel
        for channel_number in range(4):
            dynamo_devices.append(PWMOutputDevice(channel_number))
        # Rotate the dynamos through the on/off states
        for state_value in [0, 1, 0, 1]:
            dynamo_devices = apply_dynamo_state(dynamo_devices, state_value)
            print("Dynamo state:", [channel.value for channel in dynamo_devices])
            time.sleep(1)
    except KeyboardInterrupt:
        print("Stopping dynamo PWM")
    finally:
        # Release the dynamo PWM devices on exit
        for dynamo_device in dynamo_devices:
            dynamo_device.close()

from gpiozero import DigitalOutputDevice
import time

# GPIO pins wired to the 7-segment display driver outputs
SEGMENT_PINS = [DigitalOutputDevice(4), DigitalOutputDevice(5), DigitalOutputDevice(6),
                 DigitalOutputDevice(13), DigitalOutputDevice(17), DigitalOutputDevice(22),
                 DigitalOutputDevice(27)]

def write_display(display_device, value_text):
    """Write a text value to the 7-segment display using gpiozero."""
    # Each segment is a boolean output, so set each digit pin
    for digit_index, digit_value in enumerate(value_text):
        display_device[digit_index].value = digit_value

def main():
    """Continuously update the 7-segment display on the Raspberry Pi."""
    # Report the current state of the display every second
    try:
        while True:
            write_display(SEGMENT_PINS, "0123456789")
            time.sleep(0.01)
    except KeyboardInterrupt:
        print("Display update stopped")
    finally:
        # Release the display device on exit
        for display_device in SEGMENT_PINS:
            display_device.close()

if __name__ == "__main__":
    main()

# Digital output control for a Raspberry Pi classroom demo
# Drives three GPIO pins using gpiozero on the Broadcom pin numbering
from gpiozero import DigitalOutputDevice
import time

# BCM pin assignments for the digital outputs
OUTPUT_PINS = [DigitalOutputDevice(5), DigitalOutputDevice(6), DigitalOutputDevice(12)]

def drive_outputs(output_states):
    """Apply a sequence of boolean output states to the driven pins."""
    # Set each pin according to the requested state list
    for pin_device, state_value in output_states.items():
        pin_device.value = state_value

def read_outputs():
    """Return the current boolean state of each driven output pin."""
    # Read the current value of each gpiozero pin
    return {pin_device: pin_device.value for pin_device in OUTPUT_PINS}

def main():
    """Drive the digital outputs a few times and report the result."""
    # Run three cycles of driving the outputs
    for cycle_index in range(3):
        output_states = {pin_device: True if cycle_index % 2 == 0 else False
                        for pin_device in OUTPUT_PINS}
        drive_outputs(output_states)
        result_state = read_outputs()
        print("Cycle", cycle_index, "state:", result_state)
        time.sleep(1)
    print("Demo complete")

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("Demo stopped by user")
    finally:
        # Release the gpiozero devices on exit
        for output_device in OUTPUT_PINS:
            output_device.close()

from gpiozero import DigitalOutputDevice
import time

# GPIO pins wired to the four relay modules on the Raspberry Pi
RELAY_PINS = [DigitalOutputDevice(5), DigitalOutputDevice(6), DigitalOutputDevice(20), DigitalOutputDevice(21)]

def apply_relay_state(relay_device, relay_index, state_value):
    """Energise or de-energise one of the four relays."""
    # Set the relay output to the requested state
    relay_device.value = state_value
    print("Relay", relay_index, "set to", state_value)

def validate_reading(reading_value):
    """Return True when the reading is a valid integer value."""
    # A zero or one is a valid relay state
    return isinstance(reading_value, int) and reading_value in (0, 1)

if __name__ == "__main__":
    # Apply a sequence of relay states for the demonstration
    try:
        for relay_index in range(len(RELAY_PINS)):
            apply_relay_state(RELAY_PINS[relay_index], relay_index, 1 if relay_index % 2 == 0 else 0)
            time.sleep(1)
    except ValueError as read_error:
        # Handle a malformed command sent to the GPIO interface
        print("Relay control error:", read_error)
    finally:
        # Release all relay devices on the Raspberry Pi
        for relay_device in RELAY_PINS:
            relay_device.close()
